import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"pageId":"glossary","contentRevision":2},"headers":[],"relativePath":"en/glossary.md","filePath":"en/glossary.md"}'),i={name:"en/glossary.md"};function o(d,t,n,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Canonical save</td><td>Colony state accepted by the server</td></tr><tr><td>Escrow</td><td>Items, pawns or silver held by the server until an operation settles</td></tr><tr><td>Mail / parcel</td><td>Delivery or return of escrow to a recipient</td></tr><tr><td>Outbox</td><td>Local journal of unanswered outgoing requests</td></tr><tr><td>Live / host / guest</td><td>Active-map session with one authoritative host</td></tr><tr><td>Alliance / guild</td><td>Social group; guilds reuse existing alliances</td></tr><tr><td>defName</td><td>Technical item identifier such as Steel</td></tr><tr><td>Scope</td><td>Set of administrative API permissions</td></tr><tr><td>Pin</td><td>Fingerprint of a trusted TLS certificate</td></tr></tbody></table><h3 id="recovery-identifiers" tabindex="-1">Recovery identifiers <a class="header-anchor" href="#recovery-identifiers" aria-label="Permalink to &quot;Recovery identifiers&quot;">​</a></h3><ul><li><strong>SaveGeneration / generation</strong>: a colony lifetime; reset makes previous local saves stale.</li><li><strong>SaveWriteEpoch / write epoch</strong>: authority to write the current timeline; rollback changes the epoch and fences stale sessions without creating a new colony.</li><li><strong>Save version</strong>: a server snapshot number; neither the software version nor generation/epoch.</li></ul><h2 id="state-terms" tabindex="-1">Which state terms must not be confused during recovery? <a class="header-anchor" href="#state-terms" aria-label="Permalink to &quot;Which state terms must not be confused during recovery? {#state-terms}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Not the same as</th><th>Practical consequence</th></tr></thead><tbody><tr><td>Rimlink version</td><td>Save version</td><td>Updating the mod does not select a colony snapshot</td></tr><tr><td>ProtocolVersion</td><td>RimWorld version</td><td>It checks a network contract, not DLC availability</td></tr><tr><td>SaveGeneration</td><td>SaveWriteEpoch</td><td>Reset starts a colony lifetime; rollback changes write authority</td></tr><tr><td>Escrow</td><td>Mail</td><td>An escrowed offer has not yet reached its recipient</td></tr><tr><td>request_id</td><td>Trade id</td><td>Replaying intent uses the original request_id</td></tr><tr><td>Host</td><td>Dedicated server</td><td>In live, host means the map owner&#39;s game</td></tr><tr><td>Tick</td><td>Real hours</td><td>Pausing a map does not pause a server offer deadline</td></tr><tr><td>Alliance</td><td>Coop</td><td>Social membership grants no pawn control</td></tr></tbody></table><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Configuration keys, commands, error codes and defNames are not translated. A visit copy and a real raid pawn have different risks.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./players/raids-incidents">Raids and paid incidents</a></li><li><a href="./admins/security-auth">TLS, authentication and permissions</a></li></ul>',12)])])}const p=e(i,[["render",o]]);export{m as __pageData,p as default};
